 const std::set<std::string>device_names={"engineHealth","ammoBayHealth","fuelTankHealth","radioHealth","leftTrackHealth","rightTrackHealth","gunHealth","turretRotatorHealth","surveyingDeviceHealth"},crew_names={"commander","driver","gunner1","gunner2","loader1","loader2","radioman1","radioman2"};if((kind=="repairkit"&&!all&&!device_names.count(selected))||(kind=="medkit"&&!all&&!crew_names.count(selected))||((kind!="repairkit"&&kind!="medkit")&&!null(m.get("selected"))))return complete(false,"invalid_equipment_target");if(kind=="extinguisher"&&contract.get("autoactivate").truth())return complete(false,"automatic_only");
 if(intField(row,"usesLeft")==0||equipment_ready_[sender.id][equipment_id]>double(state_.server_tick)/30.)return complete(false,"equipment_ineligible");auto state=combat(*actor);const bool stunned=state.stun_end_server_time_ms>state_.server_time_ms;bool eligible=false;if(kind=="extinguisher")eligible=state.critical.fire;else if(kind=="repairkit"){for(const auto&d:state.critical.devices)if((d.second.destroyed||d.second.critical)&&(all||d.first==selected))eligible=true;}else if(kind=="medkit")eligible=stunned||(all?!state.critical.crew_ko.empty():state.critical.crew_ko.count(selected)!=0);else if(toggle)eligible=row.get("active").truth()!=m.get("requested_active").truth();if(!eligible)return complete(false,"equipment_ineligible");
